{
  "ledger": {
    "p46:e316": {
      "state": "represented",
      "fact_ids": ["P0046F0001", "P0046F0010", "P0046R0F0008"],
      "note": "D2H 복사 오버헤드가 backward→forward 계산 이득을 초과했다는 내용이 세 사실에 중복 보존됨. 조건(40000번*eps 반복)도 보존됨."
    },
    "p46:e317": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "누락: '저걸 false로 바꾸고 테스트해보자'는 결정과 '단일 플래그가 forward에서 중간 계산 결과+최종 결과까지 D2H 복사를 제어했다'는 내용이 어떤 approved_fact에도 보존되지 않음. 플래그 분리(e318)는 보존됐으나, 분리 이전의 단일 플래그 역할과 false 전환 테스트 결정이라는 연구 맥락이 빠짐."
    },
    "p46:e318": {
      "state": "represented",
      "fact_ids": ["P0046F0002", "P0046R0F0010", "P0046R0F0011"],
      "note": "forward 플래그 3개(중간 결과/final_affine/최종 결과), backward 플래그 2개 분리 내용이 보존됨."
    },
    "p46:e319": {
      "state": "represented",
      "fact_ids": ["P0046F0003", "P0046R0F0012"],
      "note": "forward 최종 계산 D2H 복사 비효율 및 정확한 테스트 위한 최적화 진행 내용이 보존됨."
    },
    "p46:e320": {
      "state": "represented",
      "fact_ids": ["P0046F0004", "P0046R0F0013"],
      "note": "forward 최적화로 backward 대비 속도 문제 '일단 해결' 내용이 보존됨. 일시적 해결이라는 한계도 명시됨."
    },
    "p46:e321": {
      "state": "no_research",
      "fact_ids": [],
      "note": "구분선(====)으로 연구 내용 없음."
    },
    "p46:e322": {
      "state": "represented",
      "fact_ids": ["P0046F0005", "P0046R0F0014"],
      "note": "단일 테스트 기준 3배 차이 기대와 다중 데이터셋 실제 미도달, Nsight System 분석 사용 결정이 보존됨. '3배'의 산출 근거는 한계로 명시됨."
    },
    "p46:e323": {
      "state": "represented",
      "fact_ids": ["P0046F0006", "P0046R0F0015"],
      "note": "단일 데이터 기준 forward/backward 각각 memcpy 6번 보존됨. 측정인지 추정인지 모호하다는 한계도 명시됨."
    },
    "p46:e324": {
      "state": "no_research",
      "fact_ids": [],
      "note": "'나는 여기서'는 연결 조각으로 독립 연구 내용 없음."
    },
    "p46:e325": {
      "state": "represented",
      "fact_ids": ["P0046F0007", "P0046R0F0016"],
      "note": "초기 추정: 입력±eps, 가중치, bias, upper, lower = 총 6개 보존됨."
    },
    "p46:e326": {
      "state": "represented",
      "fact_ids": ["P0046F0007", "P0046R0F0017"],
      "note": "가중치/bias는 nvtx 이전 prepare network on gpu로 일괄 업로드된다는 내용이 보존됨."
    },
    "p46:e327": {
      "state": "represented",
      "fact_ids": ["P0046F0008", "P0046R0F0017"],
      "note": "입력±eps + upper + lower = 4번만 복사하면 되지 않는지 재검토 내용이 보존됨."
    },
    "p46:e328": {
      "state": "no_research",
      "fact_ids": [],
      "note": "'아 ..'는 감탄/연결 조각으로 독립 연구 내용 없음."
    },
    "p46:e329": {
      "state": "represented",
      "fact_ids": ["P0046F0009"],
      "note": "신경망 추론 결과의 입력값(H2D), 추론값(D2H) 보존됨. P0046R0F0018은 e331만 커버하고 e329의 H2D/D2H 구분을 별도 진술하지 않음."
    },
    "p46:e330": {
      "state": "no_research",
      "fact_ids": [],
      "note": "'그리고'는 연결 조각으로 독립 연구 내용 없음."
    },
    "p46:e331": {
      "state": "represented",
      "fact_ids": ["P0046F0009", "P0046R0F0018"],
      "note": "CROWN에서 입력±eps + upper/lower = 총 6개 보존됨."
    },
    "p46:img0:e0": {
      "state": "represented",
      "fact_ids": ["P0046R0F0023", "P0046R0F0027"],
      "note": "structured_table_manifest에 complete=true로 등록되어 전체 표가 structured_tables에 보존됨. approved_facts에는 cudaMemcpy 6개 지표 전부(P0046R0F0023)와 표 개요(P0046R0F0027)가 연결됨. 단, P0046R0F0027의 measurements 배열에는 cudaMemcpy Num Calls 1건만 구조화되어 있고, 나머지 행(cudaLaunchKernel, cudaMemset, cuLibraryGetKernel, cuKernelGetName)의 세부 수치는 observations 텍스트와 structured_tables에만 있음. 완전=true 보완 규칙상 허용되나, 측정 배열 완결성은 다소 부족."
    }
  }
}
